"1.1.14": {"q": "Cargo Ship Safety Equipment Certificate", "cat": "S", "gp": "I", "p": 25, "b": "Core", "g": [["", "SOLAS", "For this question to be answered Yes, the Record of Safety Equipment (Form E) must be available with the certificate."]], "see": "1.1.1"},
"1.1.15": {"q": "Cargo Ship Safety Radio Certificate", "cat": "S", "gp": "I", "p": 25, "b": "Core", "g": [["", "SOLAS", "For this question to be answered Yes, the Record of Radio Equipment (Form R) must be available with the certificate."]], "see": "1.1.1"},
