"1.1.18": {"q": "International Ballast Water Certificate For ships whose flag state is not yet a party to the convention, a document of compliance is acceptable in lieu of the International Ballast Water Certificate.", "cat": "S", "gp": "I", "p": 25, "b": "Core", "ref": "BWM", "see": "1.1.1"},
"1.1.19": {"q": "Certificate of Insurance in respect of Civil Liability for Oil Pollution", "cat": "S", "gp": "I", "p": 25, "b": "Core", "ref": "CLC 92", "see": "1.1.1"},
