"11.3.19": {"q": "Does the vessel have an annual Operational CII rating?", "cat": "S", "gp": "I", "p": 137, "b": "Core", "g": [["", "MEPC 351 (78) MEPC 350 (78) MARPOL Annex VI Reg. 23", "The annual Operational CII rating will be applicable beginning May 2024."]]},
