"11.3.23": {"q": "Does the vessel have an EIV Rating number?", "cat": "S", "gp": "I", "p": 137, "b": "Core", "g": [["", "MEPC 351 (78) MEPC 350 (78) MARPOL Annex VI", "Should the vessel have an EEXI Rating number, then the EIV Rating number is not applicable."]]},
"11.3.24": {"q": "If yes then provide EIV rating ____", "cat": "", "gp": "", "p": 137, "b": "Core"},
